(7692256, 1260692, 30214, '<td valign="top">Congrats Wendy, nice portrait! Has a studio feel, with the background looking like a wall, complete with soft shadows. How did you do that?</td>', 'Congrats Wendy, nice portrait! Has a studio feel, with the background looking like a wall, complete with soft shadows. How did you do that?', '2021-04-21 11:12:01.000000', NULL, 0),
(7692257, 1260555, 30214, '<td valign="top">Congrats Willem. Nice landscape! I love it when the water is lighter than the sky... us it the blue filter effect here?</td>', 'Congrats Willem. Nice landscape! I love it when the water is lighter than the sky... us it the blue filter effect here?', '2021-04-21 11:13:51.000000', NULL, 0),
